export function projectCreatorConsolidation(path, source) {
  for (const [after, before] of hunks[path] || []) {
    assert.equal(source.split(after).length - 1, 1, `Consolidation projection drift: ${path}`);
    source = source.replace(after, before);
  }
  return source;
}
